   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type ClickTypeElementProps = Omit<
  ComponentProps<typeof ClickTypeScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const ClickTypeDefaults = {
  placeholder: "Describe what you want to build...",
  prompt: "Build me a marketing site",
  hint: "New suggestion",
  accentColor: "#3577e0",
  mode: "light",
  speed: 1,
} satisfies Partial<ClickTypeElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const ClickTypeSchema = {
  placeholder: {
    type: "text-content",
    default: "Describe what you want to build...",
    description: "Placeholder",
  },
  prompt: {
    type: "text-content",
    default: "Build me a marketing site",
    description: "Prompt",
  },
  hint: {
    type: "text-content",
    default: "New suggestion",
    description: "Hint",
  },
  accentColor: {
    type: "color",
    default: "#3577e0",
    description: "Wash",
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function ClickTypeFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const ClickTypeInner = forwardRef<HTMLDivElement, ClickTypeElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...ClickTypeDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <ClickTypeFade>
            <ClickTypeScene key={key} {...rest} />
          </ClickTypeFade>
        </div>
      </Sequence>
    );
  },
);

export const ClickType = Interactive.withSchema({
  Component: ClickTypeInner,
  componentName: "<ClickType>",
  schema: ClickTypeSchema,
  wrapInSequence: true,
});
